import { Provider, renderToString } from "@rivetjs/runtime/server";
import { createRouter } from "@rivetjs/runtime/router/server";
import { resumableToString, type ResumeManifest } from "@rivetjs/runtime/server-resume";
import { App } from "./app.js";
import { PageViews } from "./page-views.js";
import { ResumeDemo } from "./resume-demo.js";
import { Services } from "./context.js";
import { createServerServices } from "./services/server.js";
export { createServerServices } from "./services/server.js";

/** Render application HTML with isolated URL/services and request cancellation. With a resume
 * manifest the page is interactive: state and the inline loader follow the content. */
export function render(
  url: URL | string,
  { signal, manifest }: { signal?: AbortSignal; manifest?: ResumeManifest } = {},
) {
  const page = () => {
    const router = createRouter(url);
    const services = createServerServices();
    return (
      <Provider token={Services} value={services}>
        <App router={router} interactive={Boolean(manifest)} />
        <PageViews router={router} />
      </Provider>
    );
  };
  return manifest ? resumableToString(page, { manifest, signal }) : renderToString(page, { signal });
}

/** Render the resumed demo page; state and the inline loader follow the content. */
export async function renderResume({ manifest, signal }: { manifest: ResumeManifest; signal?: AbortSignal }) {
  const items = await createServerServices().list(signal);
  return resumableToString(() => <ResumeDemo items={items} />, { manifest, signal });
}

