import type { Item } from "../context.js";

/** Deferred detail view shared by server lazy loading and the browser's route chunk. */
export default function Detail({
  item,
  home,
  follow,
}: {
  item: Item;
  home: string;
  follow: (event: MouseEvent, href: string) => void;
}) {
  return (
    <article id="detail" class="rounded-xl border border-slate-200 bg-white p-6">
      <a
        class="text-sm font-semibold text-teal-700 underline underline-offset-4"
        href={home}
        onClick={(event) => follow(event, home)}
      >
        Back to examples
      </a>
      <h2 class="mt-6 text-2xl font-semibold">{item.title}</h2>
      <p class="mt-4 leading-7 text-slate-600">{item.description}</p>
      <p class="mt-6 text-sm text-slate-500">
        This view loads when its route is visited. Navigation cancels work owned by the previous route.
      </p>
    </article>
  );
}

